/// <summary>
/// Transfer order shipment confirmation class
/// </summary>
class METOrderShipmentConfirmation_TransferOrder extends METOrderShipmentConfirmation
{

}

Method.Source:
/// <summary>
/// Business logic to post/ship the transfer order
/// </summary>
/// <returns>Boolean flag</returns>
public boolean post()
{
    METSalesOrderShipmentLoadLines  shipmentLoadLines;
    InventTransferParmTable         inventTransferParmTable;
    InventTransferUpd               invTranUpd;
    InventTransferJour              inventTransferJour;
    InventTransferTable             inventTransferTable;
    boolean                         ret;
    Map transferOrders = new Map(Types::String, Types::String);

    documentStatus = DocumentStatus::None;

    while select shipmentLoadLines
        group by OrderNum
        where shipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
        exists join inventTransferTable
            where shipmentLoadLines.OrderNum == inventTransferTable.TransferId  &&
                inventTransferTable.TransferStatus == InventTransferStatus::Created
    {
        inventTransferParmTable.clear();
        inventTransferParmTable.initParmDefault();
        inventTransferParmTable.ParmId = RunBaseMultiParm::getSysParmId();
        inventTransferParmTable.TransferId = shipmentLoadLines.OrderNum;
        inventTransferParmTable.UpdateType = InventTransferUpdateType::Shipment;
        inventTransferParmTable.PrintTransferReceipt = NoYes::No;
        inventTransferParmTable.ShipUpdateQty = InventTransferShipUpdateQty::All;
        inventTransferParmTable.EditLines = NoYes::Yes;
        inventTransferParmTable.ExplodeLines = NoYes::No;
        inventTransferParmTable.TransDate = metSalesOrderShipmentLoadHeader.ConfirmedShipDate;
        inventTransferParmTable.InventDimFixedReceiveList = 0;
        inventTransferParmTable.insert();

        invTranUpd = InventTransferUpdShip::newParmBuffer(inventTransferParmTable);

        invTranUpd.run();

        //CB238 - xDock process sales orders linked to transfer orders. 

        this.postSalesOrder(shipmentLoadLines.OrderNum);

        inventTransferJour = invTranUpd.parmInventTransferJour();

        if (inventTransferJour.RecId)
        {
            inventTransferJour.selectForUpdate(true);
            inventTransferJour.METShipmentId = metSalesOrderShipmentLoadHeader.ShipmentId;
            inventTransferJour.METLoadId     = metSalesOrderShipmentLoadHeader.LoadId;
            InventTransferjour.update();

            ret = true;
        }
    }

    return ret;
}

private void postSalesOrder(InventTransferId _transferId)
{
    InventTransferTable transferTable;
    METInventTransferTableExt transferTableExt;

    select transferTable
        join transferTableExt
        where transferTableExt.InventTransferTable == transferTable.RecId
        && transferTable.TransferId == _transferId
        && transferTableExt.SalesId != '';

    SalesTable salesTable;
    METSalesPickingListGenerationTaskController         salesPickingListGenerationTaskController;
    METSalesPickingListGenerationTaskContract           salesPickingListGenerationTaskContract;

    if(transferTableExt)
    {
        salesTable = SalesTable::find(transferTableExt.SalesId);
    }

    if(salesTable)
    {
        METStockReservation::construct(salesTable).process();
    }

}
